 dict(id=259,slug='fish-swim-bladder-buoyancy',title='One fish, two volumes',hook='Changing volume can change a force.',q='In a toy model with fish mass and water density fixed, which bladder size displaces more water?',options=['The larger bladder','The smaller bladder','Both displace the same water'],answer=0,explain='In this simplified comparison, fish mass and water density stay fixed while the illustrated overall volume changes. The larger volume displaces more water and increases buoyant force, all else equal. Real fish regulate gases and are more complex than this model.',recallq='A fixed-mass object in the same water expands and displaces more water. What happens to its buoyant force?',recalloptions=['It increases','It decreases','It must be zero'],recallwhy='Displacing more of the same fluid increases buoyant force in this model.',left='<ellipse cx="75" cy="66" rx="53" ry="35" fill="#c3d9df" stroke="#779aa4"/><ellipse cx="75" cy="65" rx="15" ry="10" fill="#edd6a1" stroke="#ad986c"/><text x="75" y="119" textAnchor="middle" fill="var(--fg)" fontSize="12">Smaller volume</text>',right='<ellipse cx="75" cy="66" rx="60" ry="40" fill="#c3d9df" stroke="#779aa4"/><ellipse cx="75" cy="65" rx="30" ry="20" fill="#edd6a1" stroke="#ad986c"/><text x="75" y="119" textAnchor="middle" fill="var(--fg)" fontSize="12">Larger volume</text>',source=source),
