 dict(id=262,slug='fish-lateral-line-water-motion',title='A line that senses',hook='A body surface can detect nearby movement.',q='What kind of nearby cue can a fish’s lateral-line system detect?',options=['Movement and pressure changes in water','A spoken sentence','A color printed on a distant label'],answer=0,explain='The first panel shows a line along the body; the second adds water disturbances next to it. The lateral-line system detects water movement and pressure changes. This drawing is schematic and does not tell us what a particular fish perceives.',recallq='A fish passes close by in dark water. Which cue can reach a neighboring fish’s lateral line?',recalloptions=['Water movement','Printed letters','Spoken words'],recallwhy='The lateral-line system can detect nearby water motion.',left='<path d="M15 65 Q65 24 130 65 Q65 106 15 65Z" fill="#b9d3db" stroke="#779aa4"/><path d="M30 65 H115" stroke="#d19a73" strokeWidth="4"/><text x="75" y="117" textAnchor="middle" fill="var(--fg)" fontSize="12">Lateral line</text>',right='<path d="M15 65 Q65 24 130 65 Q65 106 15 65Z" fill="#b9d3db" stroke="#779aa4"/><path d="M30 65 H115" stroke="#d19a73" strokeWidth="4"/><path d="M18 28 Q34 15 50 28 T82 28 T114 28" fill="none" stroke="#6c9fb7" strokeWidth="3"/><text x="75" y="117" textAnchor="middle" fill="var(--fg)" fontSize="12">Water movement</text>',source=noaa),
 dict(id=265,slug='fish-countershading-view',title='Look from above',hook='A color can be useful in one viewing direction.',q='A fish has a dark back and a pale belly. In this simple scene, which surface faces a predator looking down from above?',options=['The dark back','The pale belly','Both surfaces face up equally'],answer=0,explain='The above view presents the dark back against darker water. From below, the pale belly faces brighter surface light. This common form of countershading can reduce contrast, but actual visibility depends on lighting, water and the observer.',recallq='A fish has a pale belly. Which observer is likely to see that surface directly?',recalloptions=['An observer below the fish','An observer directly above the fish','An observer inside the fish'],recallwhy='A fish’s belly faces downward, so a viewer below can see it.',left='<rect x="12" y="23" width="126" height="65" rx="8" fill="#405f6c"/><ellipse cx="75" cy="55" rx="42" ry="16" fill="#344d59"/><text x="75" y="112" textAnchor="middle" fill="var(--fg)" fontSize="12">View from above</text>',right='<rect x="12" y="23" width="126" height="65" rx="8" fill="#cce0e4"/><ellipse cx="75" cy="55" rx="42" ry="16" fill="#e3e7df"/><text x="75" y="112" textAnchor="middle" fill="var(--fg)" fontSize="12">View from below</text>',source=noaa),
 dict(id=268,slug='fish-seahorse-tail-anchor',title='A tail holds on',hook='Not every tail is used in the same way.',q='A seahorse wraps its tail around a plant stem. What immediate effect can the hold provide?',options=['It can anchor the seahorse to the stem','It turns the tail into a gill','It makes the seahorse breathe air'],answer=0,explain='The second panel shows the tail curved around a stem, providing a hold. Seahorses can use their tails to grip objects and anchor themselves. The schematic depicts a possible hold, not evidence that every plant or current provides secure anchorage.',recallq='A seahorse grips a holdfast in a current. Which body part is doing the gripping?',recalloptions=['Its tail','A mammalian hand','Its teeth'],recallwhy='Seahorses can grip a holdfast with their tails.',left='<path d="M80 19 V108" stroke="#84a67d" strokeWidth="8"/><path d="M42 31 Q23 54 45 72 L56 96" fill="none" stroke="#d3a86e" strokeWidth="10" strokeLinecap="round"/><text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Near a stem</text>',right='<path d="M80 19 V108" stroke="#84a67d" strokeWidth="8"/><path d="M42 31 Q23 54 45 72 Q90 75 81 97 Q72 109 64 96" fill="none" stroke="#d3a86e" strokeWidth="10" strokeLinecap="round"/><text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Tail around stem</text>',source=noaa),
 dict(id=271,slug='fish-puffer-water-inflation',title='A larger outline',hook='A defense can change the shape of a body.',q='Underwater, many pufferfish inflate defensively by taking in what?',options=['Water','Air from the sky','Sand from the seabed'],answer=0,explain='The two panels show a compact outline and a larger inflated outline. Many pufferfish can rapidly take in water to inflate. This defense is stressful and the schematic does not depict a measured fish or recommend handling one.',recallq='A pufferfish is underwater when it inflates. Which surrounding substance can it take in for inflation?',recalloptions=['Water','Air from above the surface','Sunlight'],recallwhy='Many pufferfish inflate underwater by taking in water.',left='<ellipse cx="75" cy="65" rx="42" ry="25" fill="#d8c38c" stroke="#aa9361" strokeWidth="3"/><text x="75" y="118" textAnchor="middle" fill="var(--fg)" fontSize="12">Before</text>',right='<circle cx="75" cy="64" r="41" fill="#d8c38c" stroke="#aa9361" strokeWidth="3"/><path d="M22 66 H35 M29 59 L36 66 L29 73" stroke="#6da4bf" strokeWidth="3" fill="none"/><text x="75" y="118" textAnchor="middle" fill="var(--fg)" fontSize="12">Water enters</text>',source=noaa),
 dict(id=281,slug='fish-parrotfish-scrape',title='A bite on a surface',hook='A meal may be attached instead of swimming away.',q='Some parrotfish use beak-like teeth against a hard surface. What action does this help them perform?',options=['Scrape material from that surface','Breathe air through the beak','Launch the teeth into the water'],answer=0,explain='The second panel shows beak-like teeth contacting and scraping a surface. Some parrotfish use fused teeth to scrape or bite food and associated material from hard substrates. Species and diets vary, and the diagram is not a full account of reef feeding.',recallq='An animal has fused teeth suited to removing attached material from a rock. Which action fits that shape?',recalloptions=['Scraping','Breathing through the teeth','Firing the teeth away'],recallwhy='A beak-like surface can help scrape material from a substrate.',left='<path d="M16 63 Q54 29 100 62 Q54 96 16 63Z" fill="#a9cbd3" stroke="#6f939d"/><rect x="115" y="28" width="18" height="72" rx="4" fill="#c3aa8d"/><text x="75" y="119" textAnchor="middle" fill="var(--fg)" fontSize="12">Near a surface</text>',right='<path d="M25 63 Q61 29 107 62 Q61 96 25 63Z" fill="#a9cbd3" stroke="#6f939d"/><path d="M105 54 L118 62 L105 70" fill="#ede1c8" stroke="#9a8d79"/><rect x="119" y="28" width="16" height="72" rx="4" fill="#c3aa8d"/><path d="M112 40 V85 M105 50 L112 40 L119 50" fill="none" stroke="#d58e66" strokeWidth="3"/><text x="75" y="119" textAnchor="middle" fill="var(--fg)" fontSize="12">Scraping contact</text>',source=noaa),
