# Version 2 illustrations for the three cases identified by visual QA. These
# are schematic common-anatomy drawings, not depictions of a specific species.
def parrotfish(x):
 return f'''<g transform="translate({x} 0)"><path d="M26 57 L8 39 L10 80 L27 68Z" fill="#508c99" stroke="#315f69" strokeWidth="2"/><path d="M24 58 Q34 32 58 29 L65 19 L70 28 Q91 29 103 43 L110 55 L111 67 Q100 90 70 94 Q39 95 24 69Z" fill="#86c5c6" stroke="#315f69" strokeWidth="2"/><path d="M36 48 Q57 36 74 42 M33 62 Q52 51 71 56 M35 76 Q53 68 71 70" fill="none" stroke="#bd8fa0" strokeWidth="3"/><path d="M64 62 Q76 53 80 66 Q76 80 64 77Z" fill="#5da5ab" stroke="#315f69"/><path d="M86 48 Q82 62 86 76" fill="none" stroke="#315f69" strokeWidth="2"/><circle cx="97" cy="52" r="4" fill="#f5eee0"/><circle cx="98" cy="52" r="2" fill="#263c42"/><path d="M108 55 Q119 56 121 62 Q119 68 108 68Z" fill="#efe2bd" stroke="#987c60" strokeWidth="2"/><path d="M111 61 H120" stroke="#987c60" strokeWidth="1.5"/></g>'''

def seahorse(tail):
 return f'''<g><path d="M46 31 Q31 31 25 43 L12 47 Q6 49 9 55 L25 56 Q29 64 39 68 Q40 82 49 91 L60 86 Q53 76 57 65 L62 51 Q62 38 52 33Z" fill="#ddbb83" stroke="#987b53" strokeWidth="2"/><path d="M59 49 Q72 45 70 58 L59 62" fill="#f0d7a4" stroke="#987b53" strokeWidth="2"/><circle cx="39" cy="42" r="3" fill="#263c42"/><path d="M45 58 Q48 64 55 65 M43 70 Q48 75 55 76" fill="none" stroke="#ae8f60" strokeWidth="2"/><path d="{tail}" fill="none" stroke="#b79669" strokeWidth="8" strokeLinecap="round"/></g>'''

def shark(liver):
 body='''<path d="M23 59 L6 39 L9 76 L24 69 Q39 87 74 85 L87 96 L85 82 Q103 78 126 64 Q110 50 90 46 L72 20 L68 44 Q39 42 23 59Z" fill="#9cb4bd" stroke="#5e7984" strokeWidth="2"/><path d="M62 76 L70 92 L86 79" fill="#78939e" stroke="#5e7984" strokeWidth="2"/><path d="M99 51 V64 M104 52 V65 M109 53 V65" stroke="#5e7984" strokeWidth="1.5"/><circle cx="117" cy="56" r="2" fill="#263c42"/>'''
 return body+('''<ellipse cx="72" cy="65" rx="25" ry="10" fill="#e7c87a" stroke="#a78d4f" strokeWidth="2"/>''' if liver else '')

for c in cases:
 if c['id']==281:
  rock='''<rect x="125" y="31" width="15" height="68" rx="3" fill="#bba28a" stroke="#8f7c69"/><path d="M129 39 L135 45 M130 60 L136 66 M129 80 L136 86" stroke="#8f7c69" strokeWidth="2"/>'''
  c['left']=parrotfish(0)+rock+'''<text x="75" y="122" textAnchor="middle" fill="var(--fg)" fontSize="12">Approach</text>'''
  c['right']=parrotfish(3)+rock+'''<path d="M132 42 V82 M126 72 L132 82 L138 72" stroke="#d2805f" strokeWidth="3" fill="none"/><text x="75" y="122" textAnchor="middle" fill="var(--fg)" fontSize="12">Beak at surface</text>'''
  c['placeholder']=parrotfish(0)+rock
  c['startAlt']='Two schematic parrotfish beside a hard surface; the action is hidden.'
 if c['id']==268:
  stem='''<path d="M100 19 V108 M100 43 Q112 31 119 28 M100 63 Q87 54 82 51" fill="none" stroke="#78a477" strokeWidth="6" strokeLinecap="round"/>'''
  c['left']=stem+seahorse('M55 86 Q59 101 73 101')+'''<text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Near a stem</text>'''
  c['right']=stem+seahorse('M55 86 Q68 99 87 91 Q99 81 108 88 Q114 99 103 102 Q93 103 91 96')+'''<text x="75" y="126" textAnchor="middle" fill="var(--fg)" fontSize="12">Tail around stem</text>'''
  c['placeholder']=stem+seahorse('M55 86 Q59 101 73 101')
  c['startAlt']='Two schematic seahorses next to a plant stem; the grip is hidden.'
 if c['id']==261:
  c['left']=shark(False)+'''<text x="75" y="117" textAnchor="middle" fill="var(--fg)" fontSize="12">Body outline</text>'''
  c['right']=shark(True)+'''<text x="75" y="117" textAnchor="middle" fill="var(--fg)" fontSize="12">Oil-rich liver</text>'''
  c['placeholder']=shark(False)
  c['startAlt']='Two schematic shark profiles; the internal organ highlight is hidden.'

assert len(cases)==12 and len({x['slug'] for x in cases})==12
out=Path('src/demos/life')
if '--force' not in sys.argv and any((out/c['slug']/'Demo.tsx').exists() for c in cases):
 raise SystemExit('Refusing to overwrite existing lesson files; use --force only after reviewing changes.')
for c in cases:
 p=out/c['slug']; p.mkdir(parents=True,exist_ok=True)
 shift=c['id']%3; opts=c['options'][shift:]+c['options'][:shift]
 model={'question':c['q'],'options':opts,'answer':opts.index(c['options'][c['answer']]),'explanation':c['explain']}
 code='''"use client";
import { useRef, useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
const model = MODEL;
export default function Demo({slug}:{slug:string}) {
  const [seen,setSeen] = useState([false,false]);
  const seenRef = useRef([false,false]);
  function open(index:0|1, interact:()=>void) {
    if (seenRef.current[index]) return;
    seenRef.current[index] = true;
    setSeen([...seenRef.current]);
    interact();
  }
  return <Lesson slug={slug} predict={{question:model.question,options:model.options,answer:model.answer}} minInteractions={2} exploreHint="Open both panels and compare their evidence." reveal={()=><p>{model.explanation}</p>}>
  {({locked,interact})=><div>
    <svg viewBox="0 0 340 155" className="stage-svg" role="img" aria-label={seen[0] && seen[1] ? model.explanation : "Two evidence panels. Open both to compare."}>
      <rect x="4" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/><rect x="182" y="4" width="154" height="140" rx="12" fill="var(--bg-2)" stroke="var(--line)"/>
      <g transform="translate(6 8)">{seen[0] ? <g>LEFT</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel A</text>}</g>
      <g transform="translate(184 8)">{seen[1] ? <g>RIGHT</g> : <text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel B</text>}</g>
    </svg>
    <Row><Control disabled={locked || seen[0]} onClick={()=>open(0,interact)}>Open A</Control><Control disabled={locked || seen[1]} onClick={()=>open(1,interact)}>Open B</Control></Row>
    <p style={{fontSize:"0.8rem",color:"var(--muted)",textAlign:"center",margin:"4px 0"}}>Schematic comparison</p>
  </div>}
  </Lesson>;
}
'''.replace('MODEL',json.dumps(model,ensure_ascii=False,indent=2)).replace('LEFT',c['left']).replace('RIGHT',c['right'])
 if c['id']==256: code=code.replace('Schematic comparison','Oxygen pressure · arbitrary units')
 if c['id'] in [261,268,281]:
  # Keep a neutral recognizable animal visible before the learner commits;
  # action or internal highlights remain hidden in both locked panels.
  for letter in ['A','B']:
   old=f'<text x="75" y="75" textAnchor="middle" fill="var(--muted)" fontSize="14">Panel {letter}</text>'
   new=f'<g><g opacity="0.48">{c["placeholder"]}</g><text x="75" y="125" textAnchor="middle" fill="var(--muted)" fontSize="12">Panel {letter}</text></g>'
   code=code.replace(old,new)
  code=code.replace('"Two evidence panels. Open both to compare."',json.dumps(c['startAlt']))
  code=code.replace('<Control disabled={locked || seen[0]}','<Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[0]}').replace('<Control disabled={locked || seen[1]}','<Control style={{minHeight:44,minWidth:44}} disabled={locked || seen[1]}')
 p.joinpath('Demo.tsx').write_text(code)
 ropts=c['recalloptions'][shift:]+c['recalloptions'][:shift]
